class Meteo:
    """Météo PdC (62) — données historiques saison 2024-2025 ou synthèse."""

    def __init__(self):
        self.t_ext             = 18.0   # valeur init août
        self.hr_ext            = 85.0
        self.t_sol             = 14.0
        self.date_debut_saison = "2024-08-15"  # recalé depuis config_installation
        self._heure            = 0.0    # compteur heures simulées
        self._idx              = 0      # index dans _METEO_62
        self._use_historical   = True   # utiliser données historiques

    @property
    def t_rosee(self):
        """Point de rosée — formule de Magnus."""
        try:
            a, b = 17.27, 237.7
            alpha = (a * self.t_ext / (b + self.t_ext)) + math.log(max(self.hr_ext, 1) / 100.0)
            return round(b * alpha / (a - alpha), 2)
        except:
            return self.t_ext - 2.0

    def step(self, dt_s=None):
        """Avancer de dt_s secondes SIMULÉES — données historiques PdC (1 valeur / heure, interpolée)."""
        if dt_s is None:
            dt_s = CYCLE_SECONDES[0]
        if self._use_historical and _METEO_62:
            n    = len(_METEO_62)
            h    = self._heure + dt_s / 3600.0
            i0   = int(h) % n
            i1   = (i0 + 1) % n
            f    = h - int(h)
            (t0, hr0, ts0), (t1, hr1, ts1) = _METEO_62[i0], _METEO_62[i1]
            self.t_ext  = t0 + (t1 - t0) * f + random.gauss(0, 0.05)
            self.hr_ext = round(max(40, min(100, hr0 + (hr1 - hr0) * f + random.gauss(0, 0.5))), 1)
            self.t_sol  = round(ts0 + (ts1 - ts0) * f, 2)
            self._idx   = i0
        else:
            # Fallback : synthèse sinusoïdale
            now = datetime.now()
            h = now.hour + now.minute / 60.0
            try:
                from datetime import date as _d, timedelta as _td
                _debut = _d.fromisoformat(self.date_debut_saison)
                _jours = int(self._heure / 24) % 365
                mois   = _d.fromordinal(_debut.toordinal() + _jours).month
            except:
                mois = now.month
            t_saison = [3, 3.5, 6, 9, 13, 16, 18.5, 18, 15, 11, 7, 4][mois - 1]
            t_jour   = -4.0 * math.cos((h - 6) * math.pi / 12)
            self.t_ext  = round(t_saison + t_jour + random.gauss(0, 0.3), 1)
            hr_base     = 82 - (self.t_ext - t_saison) * 1.5
            self.hr_ext = round(max(40, min(99, hr_base + random.gauss(0, 3))), 1)
            self.t_sol  = round(self.t_sol * 0.998 + t_saison * 0.002 + random.gauss(0, 0.05), 2)

        self._heure += dt_s / 3600.0

    def to_dict(self):
        return {
            "t_ext":      round(self.t_ext, 1),
            "hr_ext":     self.hr_ext,
            "t_rosee":    self.t_rosee,
            "t_sol":      self.t_sol,
        }


def hr_air_ext_a_t_stock(meteo, t_stock):
    """HR de l'air extérieur une fois amené à la température du stock (même eau, autre T)."""
    p_sat = lambda t: 6.112 * math.exp(17.62 * t / (243.12 + t))
    return max(30.0, min(100.0, meteo.hr_ext * p_sat(meteo.t_ext) / p_sat(t_stock)))


# ===========================================================
#  BOUCLE GÉOTHERMIQUE PARTAGÉE
#  Lien thermique entre PAC stockage (condenseur) et PAC maison (évaporateur)
# ===========================================================
class BoucleGeothermique:
    """
    PAC1+PAC2 condenseur → boucle → PAC3 évaporateur
    T_boucle monte si PAC1+2 injectent plus que PAC3 ne puise
    → COP PAC3 monte (favorable en automne, stock chaud)
    """

    def __init__(self, t_init=12.0, C_sol=3000.0):  # 3000 kJ/°C pour simulation visible (réel ≈ 60000)
        """
        t_init : T initiale boucle (°C) — sol PdC typique : 10-14°C
        C_sol  : capacité thermique sol (kJ/°C) — à caler avec capteurs réels
                 sol argileux humide ~500m² capteurs horiz. : 40 000-80 000 kJ/°C
        """
        self.t_boucle = t_init
        self.C_sol    = C_sol

    def step(self, P_inject_kw, P_puise_kw, dt_s):
        """
        P_inject_kw : chaleur condenseur PAC1+2 → boucle (kW)
        P_puise_kw  : chaleur évaporateur PAC3 ← boucle (kW)
        """
        P_net = P_inject_kw - P_puise_kw
        dT = (P_net * dt_s) / self.C_sol
        self.t_boucle = max(2.0, min(20.0, self.t_boucle + dT))

    def cop_froid(self, t_evap=-1.0):
        """
        COP PAC1+2 mode froid.
        Évaporateur : glycolée → batterie ICARUS HEX (T_evap ≈ moyenne glycolée)
        Condenseur  : boucle géothermique (T_cond = T_boucle + pinch 8°C)
        Facteur 0.45 calé ICARUS HEX + Lemasson HTT42+G eau glycolée R410A
        """
        T_evap_K = t_evap + 273.15
        T_cond_K = self.t_boucle + 8.0 + 273.15
        if T_cond_K <= T_evap_K:
            return 4.0
        cop = (T_evap_K / (T_cond_K - T_evap_K)) * 0.45
        return round(max(1.5, min(4.5, cop)), 2)  # max 4.5 côté froid (réaliste)

    def cop_chaud(self, t_dep=40.0):
        """
        COP PAC3 mode chaud.
        Évaporateur : boucle géothermique (T_evap = T_boucle - pinch 5°C)
        Condenseur  : ventilo-convecteurs (T_cond = T_dep + pinch 5°C)
        Facteur 0.60 calé Lemasson HTT42+G certifié Certita : COP=4.71 @ 35°C/6°C
        """
        T_evap_K = self.t_boucle - 5.0 + 273.15
        T_cond_K = t_dep + 5.0 + 273.15
        if T_cond_K <= T_evap_K:
            return 5.0
        cop = (T_cond_K / (T_cond_K - T_evap_K)) * 0.60
        return round(max(1.5, min(5.5, cop)), 2)

    def voyant_source(self, P_inject, P_puise, marge=0.5):
        """
        BATIMENT  : chaleur du stock PDT domine (P_inject > P_puise)
        SOL       : PAC3 puise dans le sol résiduel (P_puise > P_inject)
        EQUILIBRE : échanges équilibrés
        """
        if P_inject - P_puise > marge:   return "BATIMENT"
        if P_puise - P_inject > marge:   return "SOL"
        return "EQUILIBRE"

    def to_dict(self):
        return {"t_boucle": round(self.t_boucle, 2), "C_sol": self.C_sol}


# ===========================================================
#  SIMULATEUR STOCKAGE PDT — 500 t
#  PAC1 + PAC2 Lemasson HTT42+G (15 kW chacune)
#  Allumage séquentiel — condenseurs sur boucle géothermique
# ===========================================================
class SimulateurStockage:

    def __init__(self, csg_t=6.0, csg_hr=90.0, hyst_t=1.0, hyst_hr=3.0):
        # Consignes
        self.csg_t   = csg_t
        self.csg_hr  = csg_hr
        self.hyst_t  = hyst_t
        self.hyst_hr = hyst_hr

        # État stock
        self.t_stock  = 7.2
        self.hr_stock = 88.0
        self.t_batt   = 10.0    # température batterie évaporateur ICARUS
        self.co2_ppm  = 900.0

        # Modes opératoires
        self.mode_standby     = False
        self.mode_descente    = False
        self.mode_post_recolte = False
        self.t_cible_descente = 15.0
        self.descente_h_elapsed = 0.0
        self.date_debut_campagne = "2024-09-01"
        self.semaines_stockage   = 0.0

        # PAC1 + PAC2 — allumage séquentiel
        # PAC1 : charge normale (ΔT > hyst)
        # PAC2 : charge forte (ΔT > 1.5 × hyst) — mode descente : les deux obligatoires
        self.pac1_on = False
        self.pac2_on = False
        self.pac_on  = False
        self.nb_pac  = 2          # config_installation.nb_pac_stockage
        # Cycle de froid : commencé à csg+hyst, il continue jusqu'à csg-hyst (même après un dégivrage)
        self._cycle_froid   = False
        self._p1_seule_min  = 0.0    # durée PAC1 seule (pour le renfort PAC2)
        self._t_ref_renfort = self.t_stock

        # Anti court-cycle — 30 min minimum par unité
        self._arret_pac1 = 65.0   # init à 65 → démarrage immédiat autorisé
        self._arret_pac2 = 65.0
        self._last_mode  = ""

        # Volet CO2 indépendant
        self._co2_purge = False

        # Cumuls
        self.cumul_pac_h        = 0.0
        self.duree_degivrage_min = 0.0
        self.givre              = 0.0     # 0 = batterie propre, 1 = bouchée
        self._sechage           = False   # séchage en cours (hystérésis)
        self.cumul_fc_h         = 0.0     # heures de free cooling
        self._degivrage         = False   # dégivrage en cours
        self._securite_degiv    = False   # V2 : dégivrage > 60 min → STANDBY jusqu'à action opérateur
        self.alarme_a_journaliser = None  # message à inscrire dans alarmes_log (lu par main)
        self._pr_fini           = False   # post-récolte terminé (consigne atteinte)
        self._batt_froide_min   = 0.0     # durée batterie ≤ 0,5 °C, PAC en marche
        self._dt_min            = 0.5
        self._desc_fini         = False   # descente terminée (consigne atteinte)

    # ─── SÉLECTION DU MODE ────────────────────────────────
    def _mode(self, meteo):
        t  = self.t_stock
        hr = self.hr_stock

        # Besoins
        besoin_froid = (t > self.csg_t + self.hyst_t) or \
                       ((self.pac_on or self._cycle_froid) and t > self.csg_t - self.hyst_t)
        # Séchage : démarre au-dessus de csg_hr + hyst (93 %), s'arrête sous csg_hr (90 %)
        if hr > self.csg_hr + self.hyst_hr: self._sechage = True
        if hr < self.csg_hr:                self._sechage = False
        besoin_sech = self._sechage

        # Free cooling (V2) — toutes les conditions en même temps, volet tout ou rien
        t_rosee = meteo.t_rosee
        hr_ramene = hr_air_ext_a_t_stock(meteo, t)          # HR de l'air dehors une fois à la T du stock
        ecart_fc = ECART_FC_SEC if hr < HR_FC_MIN else ECART_FC
        fc_ok = (meteo.t_ext < t - ecart_fc) and \
                (meteo.t_ext > T_EXT_FC_MIN) and \
                (t_rosee < t - 0.5) and \
                (hr_ramene < HR_RAMENEE_MAX) and \
                not (hr < HR_FC_GARDE and hr_ramene < hr)     # garde-fou perte de poids

        # Dégivrage de sécurité : sonde batterie ≤ 0,5 °C pendant 2 h de PAC d'affilée (canicule)
        if self.pac_on and self.t_batt <= T_BATT_DEGIV:
            self._batt_froide_min += self._dt_min
        else:
            self._batt_froide_min = 0.0
        if self._batt_froide_min >= DEGIV_DUREE_MIN:
            self._degivrage = True
            self._batt_froide_min = 0.0
        degiv = self._degivrage

        # Anti court-cycle — si besoin froid mais PAC pas encore disponible → mode ATTENTE (pas CYCL)
        _attente_acc = (self._arret_pac1 < 30.0) and (self.t_stock > self.csg_t - self.hyst_t)

        # ── PRIORITÉS (ordre du logigramme V2) ─────────────
        # 1. STANDBY (demandé, ou sécurité après un dégivrage inefficace)
        if self.mode_standby:
            return "STANDBY"
        if self._securite_degiv:
            return "STANDBY-SECURITE DEGIVRAGE"

        # 2. POST-RÉCOLTE (manuel) — volet si l'air le permet, sinon PAC ; fin auto à la consigne
        if self.mode_post_recolte and not self._pr_fini:
            if t <= self.csg_t:
                self._pr_fini = True
            else:
                return "POST-RÉCOLTE-VOLET" if fc_ok else "POST-RÉCOLTE-MÉCANIQUE"

        # 3. ANTI-GEL (T_stock < csg-2°C et gel extérieur)
        seuil_ag = self.csg_t - 2.0
        seuil_ag_sortie = self.csg_t - 1.0
        if t < seuil_ag and meteo.t_ext < 0.0:
            return "ANTI-GEL-CHAUFFAGE"
        if t < seuil_ag_sortie and "ANTI-GEL" in self._last_mode:
            return "ANTI-GEL-CHAUFFAGE"

        # 4. DESCENTE (manuel, -1 °C/jour) — volet si l'air le permet, sinon PAC1+2 ; fin auto
        if self.mode_descente and not self._desc_fini:
            if self.t_cible_descente <= self.csg_t and t <= self.csg_t:
                self._desc_fini = True
            elif t > self.t_cible_descente + 0.5:
                return "DESCENTE-VOLET" if fc_ok else "DESCENTE-FROID"
            else:
                return "DESCENTE-ATTENTE"                  # en avance sur la rampe : on attend

        # 5. SÉCHAGE
        #    Air frais : sans PAC, seulement si le stock n'a pas besoin de froid
        #    Condensation : la PAC tourne, l'eau condense sur la batterie (sèche ET refroidit)
        if besoin_sech:
            air_fav = (t_rosee < t) and (meteo.t_ext > t - 5) and (meteo.t_ext < t + 3)
            return "SECHAGE-AIR FRAIS" if (air_fav and not besoin_froid) else "SECHAGE-CONDENSATION"

        # 6. DÉGIVRAGE (PAC arrêtée, 2 ventilateurs sur la batterie)
        if degiv:
            return "DEGIVRAGE"

        # 7. FREE COOLING (PAC arrêtée)
        if besoin_froid and fc_ok:
            return "FREE COOLING"

        # 8. FROID MÉCANIQUE
        if besoin_froid:
            return "FROID MECANIQUE"

        # 8b. FROID MÉCANIQUE EN ATTENTE (besoin froid mais PAC en anti court-cycle)
        if _attente_acc:
            return "FROID MECANIQUE"

        # 9. VENTILATION CYCLIQUE (par défaut — consigne atteinte)
        return "VENTILATION CYCLIQUE"

    # ─── VOLETS ───────────────────────────────────────────
    def _volet_fc(self, mode):
        """Volet air neuf (tout ou rien) — free cooling, séchage air frais, modes « -VOLET »."""
        m = mode.upper()
        if "STANDBY" in m: return False
        if "FREE" in m or m.endswith("-VOLET"): return True
        if "SECH" in m and "AIR" in m: return True
        return False

    def _volet_co2(self):
        """Volet CO2 — indépendant météo, basé uniquement sur co2_ppm.
        Hystérésis : ouvre à 3500 ppm, ferme à 2000 ppm."""
        if self.co2_ppm > 3500: self._co2_purge = True
        if self.co2_ppm < 2000: self._co2_purge = False
        return self._co2_purge

    # ─── VENTILATEURS ─────────────────────────────────────
    def _ventil(self, mode):
        """0.0 / 0.5 (1 ventilateur) / 1.0 (2 ventilateurs) — tableau « ventilation par mode » V2."""
        m = mode.upper()
        if "STANDBY" in m or any(x in m for x in ["ANTI", "ALARM", "SECURIT"]): return 0.0
        if "DEGIV" in m: return DEGIV_VENTIL                  # 2 ventilateurs pleine vitesse
        if m.endswith("-VOLET"): return 1.0                   # post-récolte / descente par le volet
        if "CYCL" in m or "FREE" in m or "SECH" in m: return 1.0   # cyclique : duty 25 % dans le bilan
        if "FROID" in m or "MÉCANIQUE" in m or "MECANIQUE" in m or "DESCENTE" in m: return 0.5
        return 0.0

    # ─── ALLUMAGE SÉQUENTIEL PAC1 / PAC2 ─────────────────
    def _update_pac(self, mode, dt_min):
        """
        PAC1 + PAC2 Lemasson HTT42+G — 15 kW chacune côté stockage.
        Cycle de froid : démarre quand T > csg + hyst (ex. 7 °C), s'arrête quand T < csg - hyst (5 °C).
          PAC1 : démarre en premier.
          PAC2 : s'ajoute si T > csg + 1.5×hyst (7,5 °C), OU en renfort si la PAC1 tourne seule
                 depuis 60 min sans que la T baisse, OU en mode descente.
          Après un dégivrage, le cycle reprend (avant : abandonné vers 6,7 °C).
        Anti court-cycle : 30 min minimum d'arrêt par unité.
        """
        m = mode.upper()
        need_froid = "FROID" in m or "MÉCANIQUE" in m   # volet / free cooling / attente : PAC arrêtées
        antigel    = "ANTI-GEL" in m
        condens    = "CONDENSATION" in m                 # séchage par la batterie froide
        delta      = self.t_stock - self.csg_t

        if delta > self.hyst_t:  self._cycle_froid = True
        if delta < -self.hyst_t: self._cycle_froid = False

        if antigel:
            # Mode chauffage — PAC en sens inverse, une seule unité suffit
            self.pac1_on = True
            self.pac2_on = False
        elif condens:
            # Séchage par condensation : PAC1 tant que le stock peut encore refroidir
            if self.t_stock > self.csg_t - self.hyst_t:
                if self._arret_pac1 >= 30.0: self.pac1_on = True
            else:
                self.pac1_on = False
            self.pac2_on = self.pac2_on and self._cycle_froid and self.nb_pac >= 2
        elif need_froid:
            # PAC1 — tout le cycle de froid
            if self._cycle_froid and self._arret_pac1 >= 30.0:
                self.pac1_on = True
            elif not self._cycle_froid:
                self.pac1_on = False

            # Renfort : PAC1 seule depuis 60 min et la T ne baisse pas (journées chaudes)
            renfort = False
            if self.pac1_on and not self.pac2_on:
                self._p1_seule_min += dt_min
                if self._p1_seule_min >= RENFORT_MIN:
                    renfort = (self._t_ref_renfort - self.t_stock) <= RENFORT_PROGRES and delta > 0
                    self._p1_seule_min  = 0.0
                    self._t_ref_renfort = self.t_stock
            else:
                self._p1_seule_min  = 0.0
                self._t_ref_renfort = self.t_stock

            # PAC2 — charge forte, renfort ou descente ; s'arrête avec le cycle
            charge_forte = (delta > self.hyst_t * 1.5) or renfort or "DESCENTE" in m
            if charge_forte and self.nb_pac >= 2 and self._arret_pac2 >= 30.0:
                self.pac2_on = True
            elif not self._cycle_froid or self.nb_pac < 2:
                self.pac2_on = False
        else:
            self.pac1_on = False
            self.pac2_on = False
            self._p1_seule_min  = 0.0              # le renfort repart de zéro au prochain cycle
            self._t_ref_renfort = self.t_stock

        self.pac_on = self.pac1_on or self.pac2_on

        # Timers anti court-cycle
        if self.pac1_on: self._arret_pac1 = 0.0
        else:            self._arret_pac1 += dt_min
        if self.pac2_on: self._arret_pac2 = 0.0
        else:            self._arret_pac2 += dt_min

    # ─── PAS DE SIMULATION ────────────────────────────────
    def step(self, meteo, dt_s=30, vitesse=1):
        dt_h   = dt_s / 3600.0
        dt_min = dt_s / 60.0
        self._dt_min = dt_min
        mode   = self._mode(meteo)

        # Allumage séquentiel PAC1/PAC2
        self._update_pac(mode, dt_min)

        volet    = self._volet_fc(mode)
        ouv      = 1.0 if volet else 0.0             # volet tout ou rien
        volet_co2 = self._volet_co2()
        ventil   = self._ventil(mode)

        # ── PHYSIQUE STOCK ────────────────────────────────
        # C_TH = 500 000 kg × 3.5 kJ/kgK = 1 750 000 kJ/°C
        # C_TH_EFF réduite pour simulation visible en temps accéléré
        # Inertie réelle : en accéléré (×500) la T stock bouge quand même de façon visible
        C_TH_EFF = C_STOCK_KJ
        P_PAC    = P_PAC_FROID_KW * (int(self.pac1_on) + int(self.pac2_on))  # kW froid

        Q10 = math.pow(2.0, (self.t_stock - 5.0) / 10.0)
        P_resp = P_RESP_5C_KW * Q10
        u_eff  = UA_ENV_KW + ouv * (UA_VOLET_KW - UA_ENV_KW)
        P_env  = u_eff * (meteo.t_ext - self.t_stock)
        duty   = 0.25 if "CYCL" in mode else 1.0
        P_fans = P_FAN_KW * (2 * ventil) * duty       # 0.5 = 1 ventilateur, 1.0 = 2

        # Anti-gel : PAC en mode chauffage (+10 kW)
        if "ANTI-GEL" in mode.upper():
            P_chaud = 10.0
            P_froid = 0.0
        else:
            P_chaud = 0.0
            # Le givre isole les ailettes et freine l'air : la puissance froid baisse
            P_froid = -P_PAC * (1 - GIVRE_PERTE * self.givre) \
                      if (self.pac_on and self.t_stock > self.csg_t - self.hyst_t) else 0.0

        dT = (P_froid + P_chaud + P_resp + P_env + P_fans) * dt_s / C_TH_EFF
        self.t_stock += dT          # physique sans bruit (le bruit capteur est ajouté à la mesure envoyée)
        t_max = 30.0 if self.mode_standby else 16.0
        self.t_stock = max(2.0, min(t_max, self.t_stock))

        # ── DESCENTE TEMPÉRATURE : -1°C/jour ─────────────
        if self.mode_descente and not self._desc_fini:
            self.descente_h_elapsed += dt_h
            self.t_cible_descente = max(
                self.csg_t,
                self.t_cible_descente - (1.0 / 24.0) * dt_h
            )

        # ── HUMIDITÉ ─────────────────────────────────────
        # Avant : +0,0012 / -0,12 % PAR MESURE → trop sec en accéléré (plancher 68 %).
        # Maintenant : équilibre par minute, indépendant du pas de calcul.
        #   PAC à l'arrêt : la transpiration des tubercules pousse vers ~94 %
        #   PAC en marche : la batterie condense et sèche vers ~87 %
        #   Volet ouvert  : l'air extérieur ramené à la T du stock impose son humidité
        if volet:
            hr_cible, tau = hr_air_ext_a_t_stock(meteo, self.t_stock), 20.0
        elif self.pac_on:
            hr_cible, tau = HR_PAC_MARCHE, 90.0
        else:
            hr_cible, tau = HR_PAC_ARRET, 120.0
        self.hr_stock = hr_cible + (self.hr_stock - hr_cible) * math.exp(-dt_min / tau)
        self.hr_stock += random.gauss(0, 0.2)
        self.hr_stock  = max(60, min(99, self.hr_stock))

        # ── BATTERIE ÉVAPORATEUR ICARUS HEX ──────────────
        # PAC ON  → T batterie vers la T des ailettes : ~+1 °C avec 1 PAC, ~-2 °C avec 2 PAC, τ = 180 min
        # PAC OFF → remontée vers T_stock, τ = 25 min
        # Dégivrage → batterie à ~0 °C tant qu'il reste de la glace, puis T_stock
        # Pas de calcul exact (exp) : même comportement à ×1 et à ×500
        TAU_REF = 180.0; TAU_REM = 25.0
        T_SAT   = -2.0
        rapproche = lambda cible, tau: cible + (self.t_batt - cible) * math.exp(-dt_min / tau)

        if "ANTI-GEL" in mode.upper():
            self.t_batt = rapproche(self.t_stock + 2.0, TAU_REM)
            self.cumul_pac_h += dt_h
        elif self._degivrage:
            # Fonte : plus l'air du stock est chaud et plus il circule, plus c'est rapide
            # (20 min à 6 °C avec 1 ventilateur ; ~12 min avec 2)
            debit = self._ventil(mode) / 0.5                 # 1 = 1 ventilateur
            f_air = max(0.15, debit) ** 0.7                  # 0 ventilateur ≈ convection naturelle
            vitesse_fonte = max(0.1, self.t_stock / 6.0) * f_air / DEGIV_MIN_REF   # fraction / min
            self.givre = max(0.0, self.givre - vitesse_fonte * GIVRE_SEUIL * dt_min)
            self.duree_degivrage_min += dt_min
            self.t_batt = rapproche(0.0 if self.givre > 0 else self.t_stock, 5.0)
            if self.givre <= 0.0:
                self._degivrage = False
            elif self.duree_degivrage_min > DEGIV_MAX_MIN and not self._securite_degiv:
                # V2 : dégivrage inefficace → alarme (alarmes_log) + STANDBY jusqu'à action opérateur
                self._securite_degiv = True
                self._degivrage = False
                self.alarme_a_journaliser = (f"Stockage PDT — DÉGIVRAGE INEFFICACE ({self.duree_degivrage_min:.0f} min) : "
                                             "installation en STANDBY. Passer en STANDBY puis AUTO pour relancer.")
        else:
            self.duree_degivrage_min = 0.0
            if self.pac_on:
                t_ail     = T_AILETTE_2PAC if (self.pac1_on and self.pac2_on) else T_AILETTE_1PAC
                t_sat_eff = t_ail - max(0, (self.t_stock - 6.0) * 0.2)
                self.t_batt = rapproche(t_sat_eff, TAU_REF)
                # Givre : ailettes sous 0 °C + air humide
                if self.t_batt < 0.0:
                    f_froid = min(1.5, -self.t_batt / 2.0)
                    f_hr    = max(0.0, (self.hr_stock - 60.0) / 30.0)
                    self.givre = min(1.0, self.givre + f_froid * f_hr * dt_h / GIVRE_H_PLEIN)
            else:
                self.t_batt = rapproche(self.t_stock, TAU_REM)
                # PAC à l'arrêt, air > 0 °C : le givre fond doucement
                if self.t_stock > 1.0:
                    self.givre = max(0.0, self.givre - dt_min / (DEGIV_MIN_REF * 4))
        self.t_batt += random.gauss(0, 0.02)
        self.t_batt = max(-4.0, min(self.t_stock + 2.0, self.t_batt))

        # ── CO2 ───────────────────────────────────────────
        # Maturité tubercules : facteur décroissant sur la saison
        try:
            debut = date.fromisoformat(self.date_debut_campagne)
            self.semaines_stockage = (date.today() - debut).days / 7.0
        except:
            pass
        sem = self.semaines_stockage
        if   sem < 4:  f_mat = 2.0 - (sem / 4.0) * 0.5
        elif sem < 12: f_mat = 1.5 - ((sem - 4) / 8.0) * 0.5
        else:          f_mat = max(0.7, 1.0 - (sem - 12) / 48.0)

        CO2_EXT = 420.0
        prod_co2 = 1.80 * Q10 * f_mat

        # Dilution additive : volet thermique ET volet CO2 peuvent être simultanés
        dilution = 0.0
        if volet_co2: dilution += 0.12 * (CO2_EXT - self.co2_ppm)
        if volet:     dilution += 0.08 * ouv * (CO2_EXT - self.co2_ppm)
        if not volet_co2 and not volet:
            if ventil > 0: dilution += 0.02 * (CO2_EXT - self.co2_ppm) * ventil
            else:          dilution  = 0.005 * (CO2_EXT - self.co2_ppm)

        self.co2_ppm = max(400.0, min(8000.0, self.co2_ppm + prod_co2 + dilution + random.gauss(0, 2.0)))

        # ── CUMULS ────────────────────────────────────────
        if self.pac_on:
            self.cumul_pac_h += dt_h
        if "FREE" in mode.upper():
            self.cumul_fc_h += dt_h

        # ── SEMAINES STOCKAGE ─────────────────────────────
        self._last_mode = mode

        # ── ALARMES ───────────────────────────────────────
        alarme, niveau = None, 0
        if self.t_stock < 2.0:
            alarme = f"ANTI-GEL CRITIQUE — T={self.t_stock:.1f}°C"; niveau = 3
        elif self._securite_degiv:
            alarme = "DÉGIVRAGE INEFFICACE — STANDBY sécurité"; niveau = 3
        elif self.co2_ppm > 5000:
            alarme = f"CO2 CRITIQUE — {self.co2_ppm:.0f} ppm"; niveau = 3
        elif self.co2_ppm > 3500:
            alarme = f"CO2 ALERTE — {self.co2_ppm:.0f} ppm"; niveau = 2
        elif self.co2_ppm > 2000:
            alarme = f"CO2 ÉLEVÉ — {self.co2_ppm:.0f} ppm"; niveau = 1
        elif self.t_stock > self.csg_t + 3:
            alarme = f"T_HAUTE — {self.t_stock:.1f}°C vs csg {self.csg_t}°C"; niveau = 2

        return {
            "t_stock":             round(self.t_stock + random.gauss(0, 0.02), 2),   # bruit capteur ±0,02 °C
            "hr_stock":            round(self.hr_stock, 2),
            "t_batterie":          round(self.t_batt, 2),
            "co2_ppm":             round(self.co2_ppm, 1),
            "pac_on":              self.pac_on,
            "pac1_on":             self.pac1_on,
            "pac2_on":             self.pac2_on,
            "pac_kw":              P_PAC_FROID_KW * (int(self.pac1_on) + int(self.pac2_on)),
            "ventil_on":           ventil > 0,
            "vitesse_ventil":      ventil,  # 0=arrêt 0.5=1 ventilateur 1.0=2 ventilateurs
            "ventil_duty":         (0.25 if "CYCL" in mode else 1.0) if ventil>0 else 0.0,
            "registre_ouvert":     volet,
            "volet_co2_ouvert":    volet_co2,
            "degivrage_on":        "DEGIV" in mode.upper(),
            "t_consigne":          self.csg_t,
            "hr_consigne":         self.csg_hr,
            "mode_actif":          mode,
            "mode_manu":           False,
            "alarme_active":       alarme,
            "niveau_alarme":       niveau,
            "duree_fonct_pac_h":   round(self.cumul_pac_h, 2),
            "cumul_pac_h":         round(self.cumul_pac_h, 2),
            "cumul_fc_h":          round(self.cumul_fc_h, 2),
            "duree_degivrage_min": round(self.duree_degivrage_min, 1),
            "mode_standby":        self.mode_standby,
            "mode_descente":       self.mode_descente and not self._desc_fini,
            "t_cible_descente":    round(self.t_cible_descente, 2),
        }


# ===========================================================
#  SIMULATEUR HABITATION
#  PAC3 Lemasson HTT42+G — évaporateur sur boucle géothermique
#  Ventilo-convecteurs Z1 + Z2 + ECS
# ===========================================================
class SimulateurHabitation:

    def __init__(self, csg_z1=20.0, csg_z2=19.0, csg_ecs=55.0):
        # Consignes
        self.csg_z1  = csg_z1
        self.csg_z2  = csg_z2
        self.csg_ecs = csg_ecs
        self.hyst_ecs = 3.0
        self.csg_c1  = 26.0    # consigne climatisation Z1
        self.csg_c2  = 26.0    # consigne climatisation Z2
        self.t_bascule_clim = 17.0

        # État interne
        self.t_z1    = 19.5
        self.t_z2    = 18.8
        self.t_ecs   = 52.0
        self.t_dep   = 40.0
        self.t_ret   = 35.0

        # PAC3 — une seule PAC côté habitation
        self.pac_on  = False
        self.pac1_on = False   # alias pour cohérence panneau
        self.pac2_on = False
        self.vc1_on  = False
        self.vc2_on  = False
        self.vanne_ecs = False

        # T_dep par usage
        self.t_dep_chauf = 40.0
        self.t_dep_clim  = 7.0

        # Mémoire zones
        self.mode_z1_last = "STANDBY"
        self.mode_z2_last = "STANDBY"

        # Anti court-cycle PAC3 — 30 min minimum (même matériel SCROLL que PAC1/PAC2)
        self._temps_arret = 65.0   # init 65 → démarrage immédiat autorisé

        # Modes
        self.mode_standby_hab = False

        # Cumuls
        self.cumul_pac_h  = 0.0
        self.cumul_pac1_h = 0.0   # alias pour bilan énergie
        self.cumul_pac2_h = 0.0

    def _loi_eau(self, t_ext):
        """Loi d'eau chauffage (V2) : T_dep = 45 − 0,8 × T_ext, bornée entre 30 et 55 °C."""
        t_dep = max(30.0, min(55.0, 45.0 - 0.8 * t_ext))
        return round(t_dep + random.gauss(0, 0.3), 1)

    def step(self, meteo, dt_s=30, vitesse=1):
        dt_h   = dt_s / 3600.0
        dt_min = min(dt_s / 60.0, 2.0)
        heure  = int(getattr(meteo, "_heure", datetime.now().hour)) % 24   # heure SIMULÉE (ECS 6h–22h)

        # ── MODE STANDBY ──────────────────────────────────
        if self.mode_standby_hab:
            self.pac_on = self.pac1_on = self.pac2_on = False
            self.vc1_on = self.vc2_on  = False
            self.t_dep  = self._loi_eau(meteo.t_ext)
            TAU = 180.0
            self.t_z1 += (meteo.t_ext - self.t_z1) / TAU * dt_min + random.gauss(0, .02)
            self.t_z2 += (meteo.t_ext - self.t_z2) / TAU * dt_min + random.gauss(0, .02)
            self.t_z1 = max(5, min(35, self.t_z1))
            self.t_z2 = max(5, min(35, self.t_z2))
            self.t_ecs += (-0.01 * (self.t_ecs - 20)) * dt_h * 60 + random.gauss(0, .05)
            self.t_ecs = max(15, min(70, self.t_ecs))
            self.t_ret = self.t_dep - 5 + random.gauss(0, .2)
            self._temps_arret += dt_min
            return self._build_return("STANDBY", None, 0)

        # ── ECS PRIORITAIRE (6h–22h) ──────────────────────
        if 6 <= heure < 22 and self.t_ecs < self.csg_ecs - self.hyst_ecs and self._temps_arret >= 30:
            self.pac_on = self.pac1_on = True
            self.pac2_on = False
            self.vanne_ecs = True
            self.vc1_on = self.vc2_on = False
            self.t_dep = 55.0
            self.t_ret = self.t_dep - 5 + random.gauss(0, .2)
            chauffe = 0.5; pertes = 0.01 * (self.t_ecs - 20)
            self.t_ecs += (chauffe - pertes) * dt_h * 60 + random.gauss(0, .05)
            self.t_ecs = max(15, min(70, self.t_ecs))
            self.cumul_pac_h += dt_h; self.cumul_pac1_h += dt_h
            self._temps_arret = 0.0
            return self._build_return("ECS PRIORITAIRE", None, 0)
        elif self.t_ecs >= self.csg_ecs:
            self.vanne_ecs = False

        # ── RÉGULATION BI-ZONE ────────────────────────────
        HYST = 1.0
        # Zone 1
        if   self.t_z1 < self.csg_z1 - HYST: self.vc1_on = True;  mode_z1 = "CHAUF"
        elif self.t_z1 > self.csg_c1 + HYST:  self.vc1_on = True;  mode_z1 = "CLIM"
        elif self.mode_z1_last == "CHAUF" and self.vc1_on:
            mode_z1 = "CHAUF"
            if self.t_z1 >= self.csg_z1 + HYST: self.vc1_on = False; mode_z1 = "STANDBY"
        elif self.mode_z1_last == "CLIM" and self.vc1_on:
            mode_z1 = "CLIM"
            if self.t_z1 <= self.csg_c1 - HYST: self.vc1_on = False; mode_z1 = "STANDBY"
        else:
            self.vc1_on = False; mode_z1 = "STANDBY"

        # Zone 2
        if   self.t_z2 < self.csg_z2 - HYST: self.vc2_on = True;  mode_z2 = "CHAUF"
        elif self.t_z2 > self.csg_c2 + HYST:  self.vc2_on = True;  mode_z2 = "CLIM"
        elif self.mode_z2_last == "CHAUF" and self.vc2_on:
            mode_z2 = "CHAUF"
            if self.t_z2 >= self.csg_z2 + HYST: self.vc2_on = False; mode_z2 = "STANDBY"
        elif self.mode_z2_last == "CLIM" and self.vc2_on:
            mode_z2 = "CLIM"
            if self.t_z2 <= self.csg_c2 - HYST: self.vc2_on = False; mode_z2 = "STANDBY"
        else:
            self.vc2_on = False; mode_z2 = "STANDBY"

        self.mode_z1_last = mode_z1
        self.mode_z2_last = mode_z2
        any_clim  = (mode_z1 == "CLIM"  and self.vc1_on) or (mode_z2 == "CLIM"  and self.vc2_on)
        any_chauf = (mode_z1 == "CHAUF" and self.vc1_on) or (mode_z2 == "CHAUF" and self.vc2_on)

        # T_dep selon usage
        # RÈGLE : chauffage prioritaire — si une zone a besoin de chaud,
        # on ne peut pas envoyer d'eau froide simultanément (une seule PAC)
        self.t_dep_chauf = self._loi_eau(meteo.t_ext)
        self.t_dep_clim  = 7.0
        # Si clim ET chauf simultanés → chauffage prime (évite de refroidir la zone froide)
        if any_chauf:
            self.t_dep = self.t_dep_chauf   # chaud pour toutes les zones
        elif any_clim:
            self.t_dep = self.t_dep_clim    # froid uniquement si 0 zone en chauf
        else:
            self.t_dep = self.t_dep_chauf   # standby : loi eau par défaut

        # PAC3 — anti court-cycle 3 min
        need_pac = self.vc1_on or self.vc2_on
        if need_pac and self._temps_arret >= 30.0:
            self.pac_on = self.pac1_on = True
            self.pac2_on = False
        elif not need_pac:
            self.pac_on = self.pac1_on = self.pac2_on = False

        # Mode
        if   any_clim and any_chauf: mode = f"CLIM Z{'1' if mode_z1=='CLIM' else '2'} / CHAUF Z{'1' if mode_z1=='CHAUF' else '2'}"
        elif any_clim:  mode = "CLIM Z1+Z2" if (self.vc1_on and self.vc2_on) else ("CLIM Z1" if self.vc1_on else "CLIM Z2")
        elif any_chauf: mode = "CHAUFFAGE Z1+Z2" if (self.vc1_on and self.vc2_on) else ("CHAUFFAGE Z1" if self.vc1_on else "CHAUFFAGE Z2")
        else:
            self.pac_on = self.pac1_on = False
            self.t_dep = self._loi_eau(meteo.t_ext)
            mode = "STANDBY"

        # ── PHYSIQUE ZONES ────────────────────────────────
        # Maison ~150m² — inertie modérée
        TAU_ENV  = 180.0   # min — enveloppe
        TAU_VC_C = 20.0    # min — clim (eau 7°C)
        TAU_VC_H = 60.0    # min — chauffage (eau 35-45°C)

        # Si chauf prioritaire, les zones en clim reçoivent l'eau chaude
        # (PAC unique — on ne peut pas avoir deux T_dep simultanées)
        # La zone en clim avec eau chaude → VC simplement coupé (vc_on=False ci-dessous)
        if any_chauf:
            # Mode chauf prioritaire : seules les zones en CHAUF sont actives
            t_dep_z1 = self.t_dep_chauf
            t_dep_z2 = self.t_dep_chauf
            tau_z1   = TAU_VC_H
            tau_z2   = TAU_VC_H
            # Couper les VC des zones en clim (eau chaude incompatible)
            if mode_z1 == "CLIM": self.vc1_on = False
            if mode_z2 == "CLIM": self.vc2_on = False
        else:
            t_dep_z1  = self.t_dep_clim  if mode_z1 == "CLIM" else self.t_dep_chauf
            t_dep_z2  = self.t_dep_clim  if mode_z2 == "CLIM" else self.t_dep_chauf
            tau_z1    = TAU_VC_C if mode_z1 == "CLIM" else TAU_VC_H
            tau_z2    = TAU_VC_C if mode_z2 == "CLIM" else TAU_VC_H

        self.t_z1 += (meteo.t_ext - self.t_z1) / TAU_ENV * dt_min
        if self.vc1_on: self.t_z1 += (t_dep_z1 - self.t_z1) / tau_z1 * dt_min
        self.t_z1 += random.gauss(0, .02)
        self.t_z1  = max(5.0, min(35.0, self.t_z1))

        self.t_z2 += (meteo.t_ext - self.t_z2) / TAU_ENV * dt_min
        if self.vc2_on: self.t_z2 += (t_dep_z2 - self.t_z2) / tau_z2 * dt_min
        self.t_z2 += random.gauss(0, .02)
        self.t_z2  = max(5.0, min(35.0, self.t_z2))

        # ECS
        pertes = 0.01 * (self.t_ecs - 20)
        self.t_ecs += (-pertes) * dt_h * 60 + random.gauss(0, .05)
        self.t_ecs  = max(15, min(70, self.t_ecs))

        # Eau départ/retour
        if self.pac_on and not self.vanne_ecs:
            self.t_dep = 7.0 if (any_clim and not any_chauf) else self._loi_eau(meteo.t_ext)
        self.t_ret = self.t_dep - 5 + random.gauss(0, .2)

        # Cumuls et timer
        if self.pac_on:
            self.cumul_pac_h += dt_h; self.cumul_pac1_h += dt_h
            self._temps_arret = 0.0
        else:
            self._temps_arret += dt_min

        # Alarmes
        alarme, niveau = None, 0
        if self.t_ecs > 65:
            alarme = f"SURCHAUFFE ECS — {self.t_ecs:.1f}°C"; niveau = 3
        elif meteo.t_sol < -3:
            alarme = f"GEL CAPTEURS SOL — T_sol={meteo.t_sol:.1f}°C"; niveau = 3

        return self._build_return(mode, alarme, niveau)

    def _build_return(self, mode, alarme, niveau):
        return {
            "t_int_z1":      round(self.t_z1, 2),
            "t_int_z2":      round(self.t_z2, 2),
            "t_ecs":         round(self.t_ecs, 2),
            "t_eau_dep":     round(self.t_dep, 2),
            "t_eau_ret":     round(self.t_ret, 2),
            "pac_on":        self.pac_on,
            "pac1_on":       self.pac1_on,
            "pac2_on":       self.pac2_on,
            "pac_kw":        15.0 if self.pac_on else 0.0,
            "fancoil_z1_on": self.vc1_on,
            "fancoil_z2_on": self.vc2_on,
            "vanne_ecs_on":  self.vanne_ecs,
            "pompe_sol_on":  self.pac_on,
            "mode_actif":    mode,
            "mode_manu":     False,
            "alarme_active": alarme,
            "niveau_alarme": niveau,
            "cumul_pac_h":   round(self.cumul_pac_h, 2),
            "cumul_ecs_h":   round(self.cumul_pac_h * 0.3, 2),
        }


# ===========================================================
#  BOUCLE PRINCIPALE
# ===========================================================
def main():
    from supabase import create_client
    sb = create_client(SUPABASE_URL, SUPABASE_KEY)
    p("  Connexion Supabase OK", GREEN)

    # Consignes par défaut
    csg_t, csg_hr          = 6.0, 90.0
    csg_z1, csg_z2, csg_ecs = 20.0, 19.0, 55.0

    meteo  = Meteo()
    sto    = SimulateurStockage(csg_t=csg_t, csg_hr=csg_hr)
    hab    = SimulateurHabitation(csg_z1=csg_z1, csg_z2=csg_z2, csg_ecs=csg_ecs)
    boucle = BoucleGeothermique(t_init=12.0)  # C_sol=3000 kJ/°C par défaut (simulation visible)

    # Restaurer cumuls + horloge simulée depuis les dernières mesures
    heure_reprise = None
    # Les tables de mesures ne sont plus lisibles avec la clé publique : tout passe par simu_config()
    try:
        conf0 = sb.rpc("simu_config", {"eid": EXPLOIT_ID}).execute().data or {}
        r = conf0.get("reprise_sto")
        if r:
            sto.cumul_pac_h = float(r.get("duree_fonct_pac_h") or 0)
            sto.cumul_fc_h  = float(r.get("cumul_fc_h") or 0)
            heure_reprise   = r.get("heure_simulee")        # reprise de l'horloge simulée
        r = conf0.get("reprise_hab")
        if r: hab.cumul_pac_h = float(r.get("cumul_pac_h") or 0)
        p(f"  Cumuls restaurés — Sto:{sto.cumul_pac_h:.1f}h | Hab:{hab.cumul_pac_h:.1f}h", GREEN)
    except: pass

    p(f"  Simulation démarrée — cycle toutes les {CYCLE_SECONDES[0]}s", GREEN)
    print(f"\n  {'Cycle':<6} {'Mode Stockage':<28} {'T_stock':>8} {'T_Z1':>6} {'Boucle':>8} {'Src':>10}")
    print("  " + "─" * 72)

    cycle    = 0
    vitesse  = 1
    saison_id = None

    while True:
        cycle += 1

        # ── CONFIGURATION (un seul appel : consignes, config, briques, saison) ──
        # Avant : lecture directe des tables avec la clé anon → refusée par la sécurité (RLS),
        #         le simulateur ne voyait JAMAIS les consignes ni la vitesse ×500.
        try:
            conf = sb.rpc("simu_config", {"eid": EXPLOIT_ID}).execute().data or {}
        except Exception as e:
            conf = {}
            p(f"  Erreur config: {e}", RED)
        cfg      = conf.get("config")   or {}
        systeme  = conf.get("systeme")  or {}
        briques  = conf.get("briques")  or {}
        saison_id = conf.get("saison_id") or saison_id

        source_meteo   = cfg.get("source_meteo", "simulateur")
        # Brique Habitation absente ou inactive → pas de maison, pas de PAC3
        module_pac_hab = briques.get("habitation", False) and cfg.get("module_pac_habitation", "true") == "true"
        module_clim    = cfg.get("module_clim_maison", "true") == "true"
        module_ecs     = cfg.get("module_ecs", "true") == "true"
        sto.nb_pac     = int(cfg.get("nb_pac_stockage", "2") or 2)
        date_debut_saison = cfg.get("date_debut_saison", "2024-09-01")
        if meteo.date_debut_saison != date_debut_saison:
            meteo.date_debut_saison = date_debut_saison
            p(f"  [CFG] Recalage météo sur {date_debut_saison}", GREEN)
        try:    debut_sim = datetime.fromisoformat(date_debut_saison)
        except: debut_sim = datetime(2024, 9, 1)
        # Au démarrage : reprendre l'horloge simulée là où elle s'était arrêtée (avant : retour au début)
        if heure_reprise:
            try:
                h = (datetime.fromisoformat(heure_reprise.replace("Z", "+00:00")).replace(tzinfo=None)
                     - debut_sim).total_seconds() / 3600.0
                if h >= 0:
                    meteo._heure = h
                    p(f"  Reprise horloge simulée : {heure_reprise[:16]}", GREEN)
            except Exception: pass
            heure_reprise = None

        if systeme.get("date_debut_campagne"):
            sto.date_debut_campagne = systeme["date_debut_campagne"]
        if systeme.get("beta_actif") == "true":       # capteurs réels actifs → le simulateur se tait
            time.sleep(CYCLE_SECONDES[0]); continue

        # ── CONSIGNES ─────────────────────────────────────
        for row in conf.get("consignes") or []:
            if row["id"] == "stockage":
                vitesse = max(1, int(row.get("vitesse_sim", 1) or 1))
                CYCLE_SECONDES[0] = 1 if vitesse >= 100 else 2 if vitesse >= 50 else 6 if vitesse >= 5 else 30
                sto.csg_t   = float(row.get("csg_t")   or sto.csg_t)
                sto.hyst_t  = float(row.get("hyst_t")  or sto.hyst_t)
                sto.csg_hr  = float(row.get("csg_hr")  or sto.csg_hr)
                sto.hyst_hr = float(row.get("hyst_hr") or sto.hyst_hr)
                standby_avant    = sto.mode_standby
                sto.mode_standby = bool(row.get("mode_standby", False))
                if sto.mode_standby and not standby_avant and sto._securite_degiv:
                    sto._securite_degiv = False            # l'opérateur a pris la main : sécurité levée
                    p("  Sécurité dégivrage levée par l'opérateur", CYAN)
                descente_avant   = sto.mode_descente
                sto.mode_descente = bool(row.get("mode_descente", False))
                if sto.mode_descente and not descente_avant:
                    sto.t_cible_descente  = sto.t_stock
                    sto.descente_h_elapsed = 0.0
                    sto._desc_fini = False
                    p(f"  DESCENTE activée depuis T={sto.t_stock:.1f}°C", CYAN)
                pr_avant = sto.mode_post_recolte
                sto.mode_post_recolte = bool(row.get("mode_post_recolte", False))
                if sto.mode_post_recolte and not pr_avant:
                    sto._pr_fini = False
                    p(f"  POST-RÉCOLTE activé depuis T={sto.t_stock:.1f}°C", CYAN)
            if row["id"] == "habitation":
                hab.mode_standby_hab = bool(row.get("mode_standby_hab", False))
                hab.csg_z1   = float(row.get("csg_z1")      or hab.csg_z1)
                hab.csg_z2   = float(row.get("csg_z2")      or hab.csg_z2)
                hab.csg_ecs  = float(row.get("csg_ecs")     or hab.csg_ecs)
                hab.hyst_ecs = float(row.get("hyst_ecs")    or 3.0)
                hab.csg_c1   = float(row.get("csg_clim_z1") or hab.csg_c1)
                hab.csg_c2   = float(row.get("csg_clim_z2") or hab.csg_c2)
                hab.t_bascule_clim = float(row.get("t_bascule_clim") or hab.t_bascule_clim)

        # ── MÉTÉO ─────────────────────────────────────────
        if source_meteo == "esp32":
            try:
                r = conf.get("derniere_ext")          # dernière mesure ESP32 (via simu_config)
                if r:
                    meteo.t_ext      = float(r.get("t_ext", meteo.t_ext) or meteo.t_ext)
                    meteo.hr_ext     = float(r.get("hr_ext", meteo.hr_ext) or meteo.hr_ext)
                    meteo.wind_speed = float(r.get("wind_speed", meteo.wind_speed) or meteo.wind_speed)
                    meteo.irradiance = float(r.get("irradiance", 0) or 0)
            except: pass
        elif systeme.get("mode_meteo") == "reelle":
            try:
                m = conf.get("meteo_reelle")          # dernière météo réelle (via simu_config)
                if m:
                    meteo.t_ext      = float(m.get("t_ext",      meteo.t_ext)      or meteo.t_ext)
                    meteo.hr_ext     = float(m.get("hr_ext",     meteo.hr_ext)     or meteo.hr_ext)
                    meteo.wind_speed = float(m.get("wind_speed", meteo.wind_speed) or meteo.wind_speed)
            except: pass
        else:
            meteo.step(dt_s=CYCLE_SECONDES[0] * vitesse)   # avance du temps SIMULÉ

        # ── PAS DE SIMULATION ─────────────────────────────
        data_sto = sto.step(meteo, dt_s=CYCLE_SECONDES[0] * vitesse, vitesse=vitesse)
        if module_pac_hab:
            data_hab = hab.step(meteo, dt_s=CYCLE_SECONDES[0] * vitesse, vitesse=vitesse)
        else:
            data_hab = {"pac_on": False, "pac_kw": 0.0, "mode_actif": "DESACTIVE"}   # pas de maison → pas de PAC3

        # ── BOUCLE GÉOTHERMIQUE ───────────────────────────
        # PAC1+PAC2 condenseur → boucle (injection chaleur)
        # PAC3 évaporateur ← boucle (puisage chaleur)
        dt_sim    = CYCLE_SECONDES[0] * vitesse
        t_evap_sto = float(getattr(sto, "t_batt", -1.0))   # proxy T_glycolée
        cop_sto    = boucle.cop_froid(t_evap=t_evap_sto)
        P_froid    = data_sto.get("pac_kw", 0.0)
        P_inject   = P_froid * (1.0 + 1.0 / max(cop_sto, 0.1)) if data_sto.get("pac_on") else 0.0

        cop_hab    = boucle.cop_chaud(t_dep=float(getattr(hab, "t_dep", 35.0)))
        P_th_hab   = data_hab.get("pac_kw", 0.0)
        P_puise    = P_th_hab / max(cop_hab, 0.1) if data_hab.get("pac_on") else 0.0

        boucle.step(P_inject, P_puise, dt_sim)

        source = boucle.voyant_source(P_inject, P_puise)

        # Enrichir les données
        data_sto.update({
            "t_boucle":       round(boucle.t_boucle, 2),
            "p_inject_kw":    round(P_inject, 2),
            "cop_boucle":     cop_sto,
            "boucle_bilan_kw": round(P_inject - P_puise, 2),
            "source_chaleur": source,
        })
        data_hab.update({
            "t_boucle":    round(boucle.t_boucle, 2),
            "p_puise_kw":  round(P_puise, 2),
            "cop_boucle":  cop_hab,
            "source_chaleur": source,
        })

        # ── PUSH SUPABASE ─────────────────────────────────
        # Ajouter exploitation_id à toutes les données
        meteo_dict = meteo.to_dict()
        meteo_dict["exploitation_id"] = EXPLOIT_ID
        data_sto["exploitation_id"] = EXPLOIT_ID
        data_hab["exploitation_id"] = EXPLOIT_ID
        if saison_id:
            meteo_dict["saison_id"] = data_sto["saison_id"] = data_hab["saison_id"] = saison_id
        data_sto["heure_simulee"] = data_hab["heure_simulee"] = (debut_sim + timedelta(hours=meteo._heure)).isoformat()

        try:
            # returning="minimal" : la clé publique peut écrire mais plus relire les mesures
            sb.table("conditions_externes").insert(meteo_dict, returning="minimal").execute()
        except: pass

        try:
            sb.table("stockage_readings").insert(data_sto, returning="minimal").execute()
            if sto.alarme_a_journaliser:
                sb.table("alarmes_log").insert({"exploitation_id": EXPLOIT_ID, "source": "simulateur:degivrage",
                                                "niveau": 3, "message": sto.alarme_a_journaliser},
                                               returning="minimal").execute()
                sto.alarme_a_journaliser = None
            if module_pac_hab:
                sb.table("habitation_readings").insert(data_hab, returning="minimal").execute()
        except Exception as e:
            p(f"  ERREUR cycle {cycle}: {e}", RED)
            time.sleep(10); continue

        # Cumuls : envoyés dans chaque mesure (duree_fonct_pac_h / cumul_pac_h), plus d'écriture dans consignes
        # Alertes : vérifiées par Supabase (cron toutes les 5 min), plus besoin de les appeler ici

        # Archive 24h
        if cycle % 2880 == 0 and cycle > 0:
            try:
                urllib.request.urlopen(urllib.request.Request(
                    "https://diqxglwsffrlfziymplm.supabase.co/functions/v1/geofresh-alertes",
                    data=json.dumps({"action": "archive"}).encode(),
                    headers={"Content-Type": "application/json", "Authorization": f"Bearer {SUPABASE_KEY}"},
                    method="POST"
                ), timeout=10)
                p("  Archive 24h OK", GREEN)
            except: pass

        # Console
        mode_s = data_sto.get("mode_actif", "?")[:26]
        t_s    = float(data_sto.get("t_stock", 0))
        t_z1   = float(data_hab.get("t_int_z1", 0))
        t_b    = boucle.t_boucle
        src    = source[:10]
        p1     = "●" if sto.pac1_on else "○"
        p2     = "●" if sto.pac2_on else "○"
        p3     = ("●" if hab.pac_on else "○") if module_pac_hab else "–"
        print(f"  {cycle:<6} {mode_s:<28} {t_s:5.1f}°C  {t_z1:5.1f}°C  {t_b:5.1f}°C  {src:<10}  P1{p1} P2{p2} P3{p3}  x{vitesse}")

        time.sleep(CYCLE_SECONDES[0])


# ===========================================================
#  POINT D'ENTRÉE
# ===========================================================
if __name__ == "__main__":
    while True:
        try:
            main()
        except KeyboardInterrupt:
            print("\n  Arrêt demandé.")
            break
        except Exception as e:
            p(f"\n  ERREUR FATALE : {e}", RED)
            p("  Redémarrage dans 30s...", RED)
            time.sleep(30)
